// ─────────────────────────────────────────────
// Parse snapshot and build alert rules
// ─────────────────────────────────────────────
const snap = $input.first().json;

const weather  = snap.weather_latest  || {};
const sensor   = snap.sensor_latest   || {};
const relay    = snap.relay_status    || {};
const ai       = snap.ai_latest_decision || {};
const alarm    = snap.alarm           || {};
const stats24  = snap.weather_stats_24h || {};

// ── Alert conditions ─────────────────────────
const alerts = [];

if (alarm.active) {
  alerts.push({ level: 'CRITICAL', msg: `🚨 Alarm Active: ${alarm.reason}` });
}

if ((weather.rain_probability || 0) >= 70) {
  alerts.push({ level: 'WARNING', msg: `🌧 Rain Probability: ${weather.rain_probability}% — Consider closing the greenhouse` });
}

if ((weather.temperature || 0) >= 38) {
  alerts.push({ level: 'WARNING', msg: `🌡 Outdoor temp high: ${weather.temperature}°C` });
}

if ((weather.aqi || 0) >= 4) {
  alerts.push({ level: 'WARNING', msg: `🏭 AQI ${weather.aqi} (${weather.aqi_label}) — PM2.5: ${weather.pm2_5} μg/m³` });
}

if ((sensor.temperature || 0) >= 35) {
  alerts.push({ level: 'WARNING', msg: `🌡 Indoor sensor temp high: ${sensor.temperature}°C` });
}

if ((sensor.humidity || 0) >= 90) {
  alerts.push({ level: 'INFO', msg: `💧 Indoor humidity high: ${sensor.humidity}%` });
}

// ── Daily report flag ─────────────────────────
const now = new Date();
const isDailyReportTime = (now.getHours() === 7 && now.getMinutes() < 15);

// ── Summary message ───────────────────────────
const summaryLines = [
  `📡 IoT Dashboard — ${snap.server_time}`,
  ``,
  `🌤 Weather (${weather.city_name || 'Nakhon Si Thammarat'})`,
  `  Temp: ${weather.temperature}°C | Feels: ${weather.feels_like}°C | Humidity: ${weather.humidity}%`,
  `  Wind: ${weather.wind_speed} m/s | Clouds: ${weather.clouds}% | Rain Prob: ${weather.rain_probability}%`,
  `  Condition: ${weather.weather_desc} | AQI: ${weather.aqi} (${weather.aqi_label})`,
  `  PM2.5: ${weather.pm2_5} μg/m³ | PM10: ${weather.pm10} μg/m³`,
  ``,
  `🌡 Sensor (${sensor.device_name})`,
  `  Indoor: ${sensor.temperature}°C | Humidity: ${sensor.humidity}% | DS18B20: ${sensor.ds18b20}°C`,
  ``,
  `🔌 Relay: R1=${relay.relay1} R2=${relay.relay2} R3=${relay.relay3}`,
  `🤖 AI: ${ai.decision || 'N/A'} (${(ai.confidence||0)*100|0}% confidence)`,
];

if (alerts.length) {
  summaryLines.push(`\n⚠️ ALERTS:\n` + alerts.map(a => `  [${a.level}] ${a.msg}`).join('\n'));
}

return [{
  json: {
    has_alerts:        alerts.length > 0,
    alerts,
    is_daily_report:   isDailyReportTime,
    summary_message:   summaryLines.join('\n'),
    // pass-through for downstream nodes
    weather,
    sensor,
    relay,
    ai,
    alarm,
    stats24,
    server_time: snap.server_time,
  }
}];
